import{_ as i,c as t,o as s,aj as a}from"./chunks/framework.BlveriQe.js";const m=JSON.parse('{"title":"One App, Several Clients","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/multi-client.md","filePath":"getting-started/multi-client.md"}'),n={name:"getting-started/multi-client.md"};function o(d,e,r,h,l,p){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="one-app-several-clients" tabindex="-1">One App, Several Clients <a class="header-anchor" href="#one-app-several-clients" aria-label="Permalink to “One App, Several Clients”">​</a></h1><p>A product with a web app and a native app is <strong>one Primitive app</strong>: one app ID, one set of environments, one server configuration, one model schema. The two clients are two front ends onto the same backend, and the things they share are the things that are expensive to get wrong — a second copy of the model schema silently orphans records, a second app ID splits your users in half.</p><p><code>primitive init</code> scaffolds that repository for you, and the layout it produces is the one this page describes.</p><h2 id="scaffolding-both-clients" tabindex="-1">Scaffolding both clients <a class="header-anchor" href="#scaffolding-both-clients" aria-label="Permalink to “Scaffolding both clients”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web,ios</span></span></code></pre></div><p><code>--platform</code> takes one platform or a comma-separated list; run it interactively and the prompt lets you select both. One run creates the app, downloads both templates, and produces:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>  .primitive/config.json          # the environments: backend URL + app ID per environment</span></span>
<span class="line"><span>  .primitive/sync/&lt;env&gt;/&lt;appId&gt;/  # your app&#39;s server configuration, as TOML</span></span>
<span class="line"><span>  models/models.toml              # the model schema — one copy, shared</span></span>
<span class="line"><span>  AGENTS.md                       # what this repo is and what is shared</span></span>
<span class="line"><span>  web/                            # the Vue client: its own package.json, .env, AGENTS.md</span></span>
<span class="line"><span>  ios/                            # the SwiftUI client: its own project, AGENTS.md</span></span></code></pre></div><p>There is one git repository, at the root, with one initial commit. There is no root <code>package.json</code> and no workspace file: the clients are independent projects sitting side by side, each with its own dependencies, build, tests and deploy. What they share sits above them.</p><p>A single-platform <code>primitive init my-app</code> still produces the flat single-client project it always has — the client is the repository.</p><h2 id="adding-a-client-later" tabindex="-1">Adding a client later <a class="header-anchor" href="#adding-a-client-later" aria-label="Permalink to “Adding a client later”">​</a></h2><p>You do not have to decide up front. Run init from inside the repository, pointing at the new client&#39;s directory:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or just \`primitive init --platform ios\`</span></span></code></pre></div><p>Name the directory or leave it out — one platform goes in a directory named after itself. Init walks up to your project&#39;s <code>.primitive/config.json</code> and adds the client to <strong>that</strong> app: the app ID and backend URL come from the selected environment, and the new client is wired to the repository&#39;s model schema. It creates no second app, no second <code>.primitive/</code>, and no second git repository — and it makes no commit, so you can review the new files with <code>git status</code> and commit them yourself.</p><p>If your repository is a single client at the root, adding a second one moves the model schema up to <code>my-app/models/models.toml</code> and rewires the existing client to read it there, after asking you. Nothing else about that client moves: its <code>package.json</code>, sources and build config stay exactly where they are.</p><p>For CI and scripted setup, <code>.primitive-init.toml</code>:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;add-client&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">platform = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ios&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">promote_schema = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # consent to move a single-client repo&#39;s schema to the root</span></span></code></pre></div><h2 id="what-is-shared-and-what-is-not" tabindex="-1">What is shared and what is not <a class="header-anchor" href="#what-is-shared-and-what-is-not" aria-label="Permalink to “What is shared and what is not”">​</a></h2><table tabindex="0"><thead><tr><th>Per app — at the repository root</th><th>Per client — in its own directory</th></tr></thead><tbody><tr><td>Environments and the app ID (<code>.primitive/config.json</code>)</td><td>Generated code (models, workflow invokers, database types)</td></tr><tr><td>Server configuration (<code>.primitive/sync/&lt;env&gt;/&lt;appId&gt;/</code>)</td><td>Runtime connection settings</td></tr><tr><td>The model schema (<code>models/models.toml</code>)</td><td>Dependencies, build and test configuration</td></tr><tr><td>App secrets and config vars</td><td>Deploy configuration</td></tr><tr><td>The app-wide <code>AGENTS.md</code></td><td>The client&#39;s own <code>AGENTS.md</code></td></tr></tbody></table><p>Workflows, database types and the rest of your <a href="./configuring-primitive-services.html">server configuration</a> are defined once for the app. The typed code generated from them is per client — each client runs its own codegen, in its own language, into its own source tree.</p><h2 id="the-model-schema" tabindex="-1">The model schema <a class="header-anchor" href="#the-model-schema" aria-label="Permalink to “The model schema”">​</a></h2><p><code>models/models.toml</code> is the app&#39;s one schema, and it is never copied. The TOML keys are the field names on the wire, so two copies that drift apart write records the other cannot read.</p><p>Each client points at that one file:</p><ul><li>The web client&#39;s codegen reads it and its generated model barrel imports it, so the schema it generates from and the schema it loads at runtime are the same file.</li><li>The Swift client names it in <code>bao-codegen.json</code> beside its sources, which is what its codegen — SwiftPM and Xcode alike — reads.</li></ul><p>A client&#39;s template ships code generated from its own starter models, so adding a client adds any of those models the schema does not already declare, and says which ones. Models you already have keep their definitions exactly as they are.</p><p>To change a model: edit <code>models/models.toml</code>, then run each client&#39;s codegen (<code>pnpm codegen</code> in the web client, <code>bash scripts/codegen.sh</code> in the Swift one). See <a href="./choosing-your-data-model.html">Choosing Your Data Model</a> for what belongs in the schema in the first place.</p><h2 id="running-commands" tabindex="-1">Running commands <a class="header-anchor" href="#running-commands" aria-label="Permalink to “Running commands”">​</a></h2><p>Every <code>primitive</code> command walks up from where you run it to the nearest <code>.primitive/config.json</code>, the way git finds its repository. Run <code>primitive config diff</code> in <code>web/</code>, in <code>ios/</code>, or at the root and it resolves the same project, the same environment and the same config directory. No path flag, no per-client setup.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to “Environments”">​</a></h2><p>An environment is a backend and an app together, and it belongs to the app rather than to one client:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # every command in this repository now targets staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or name one per command</span></span></code></pre></div><p><code>primitive env use</code> writes this machine&#39;s selection, not a tracked file, so it is yours and not your teammates&#39;. Each client resolves its own runtime connection settings from that same project config, so pointing the repository at an environment points both clients at the same backend and app.</p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to “AGENTS.md”">​</a></h2><p>The root <code>AGENTS.md</code> describes the app: the layout, what is shared, where the schema is. Each client keeps its own, describing its stack and conventions, and it ships with that client&#39;s template — so app-wide facts belong in the root file, which upgrades never touch.</p>`,33)])])}const g=i(n,[["render",o]]);export{m as __pageData,g as default};
